 void checkUpdate(boolean manual){if(manual)toast("Перевіряємо оновлення…");new Thread(()->{try{URL u=new URL("https://api.github.com/repos/1796caesar-cmd/AbonClient/releases/latest");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","AbonClient");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}finally{c.disconnect();}JSONObject r=new JSONObject(out.toString("UTF-8"));String tag=r.optString("tag_name");int remote=Integer.parseInt(tag.substring(tag.lastIndexOf('-')+1));String download="";JSONArray assets=r.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if(a.optString("name").equals("AbonClient.apk"))download=a.optString("browser_download_url");}final String link=download;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;if(remote>versionCode()&&link.startsWith(REPO+"/releases/download/"))dialog().setTitle("Доступне оновлення").setMessage(r.optString("name",tag)).setNegativeButton("Пізніше",null).setPositiveButton("Завантажити та встановити",(d,w)->updater.download(link,remote)).show();else if(manual)toast("Новішої версії не знайдено");});}catch(Exception e){if(manual)runOnUiThread(()->toast("Не вдалося перевірити оновлення"));}}).start();}
 void settlementTable(LinearLayout parent,JSONArray rows){
  LinearLayout table=new LinearLayout(this);table.setOrientation(1);parent.addView(table,new LinearLayout.LayoutParams(-1,-2));
  addTableRow(table,new String[]{"Дата","Нараховано","Сплачено","Залишок"},true,0);
  for(int i=0;i<Math.min(3,rows.length());i++){JSONArray r=rows.optJSONArray(i);if(r==null||r.length()<4)continue;String date=r.optString(0);if(date.matches("[0-9]{4}-[0-9]{2}"))date=date.substring(5)+"."+date.substring(0,4);addTableRow(table,new String[]{date,r.optString(1).replace('.',','),r.optString(2).replace('.',','),r.optString(3).replace('.',',')},false,i);}
  text(parent,"Усі суми в гривнях",12,dark,false);
 }
 void addTableRow(LinearLayout table,String[] values,boolean header,int index){
  LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackgroundColor(header?blend(green,surface,.84f):(index%2==0?bg:surface));
  for(int i=0;i<4;i++){TextView cell=new TextView(this);cell.setText(values[i]);cell.setTextSize(header?10:12);cell.setTextColor(header?accentText:dark);cell.setGravity(Gravity.CENTER);cell.setPadding(dp(1),dp(10),dp(1),dp(10));if(header)cell.setTypeface(null,Typeface.BOLD);row.addView(cell,new LinearLayout.LayoutParams(0,-2,i==1?1.2f:1f));}
  table.addView(row,new LinearLayout.LayoutParams(-1,-2));
 }
